	"encoding/base64"
	"encoding/json"
	"net/http"
	"os"
	"strings"
	"time"
)

const SECRET = "my-jwt-secret"

type User struct {
	Password string `json:"password"`
	Role     string `json:"role"`
}

var users = map[string]User{
	"admin": {"admin123", "admin"},
	"user1": {"user123", "user"},
}

func base64Url(data []byte) string {
	return strings.TrimRight(base64.URLEncoding.EncodeToString(data), "=")
}

func createToken(payload map[string]interface{}) string {
	header := base64Url(jsonBytes(map[string]string{"alg": "HS256", "typ": "JWT"}))
	body := base64Url(jsonBytes(payload))
	mac := hmac.New(sha256.New, []byte(SECRET))
	mac.Write([]byte(header + "." + body))
	signature := base64Url(mac.Sum(nil))
	return header + "." + body + "." + signature
}

func verifyToken(token string) map[string]interface{} {
	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		return nil
	}
	header, body, signature := parts[0], parts[1], parts[2]
	mac := hmac.New(sha256.New, []byte(SECRET))
	mac.Write([]byte(header + "." + body))
	expectedSig := base64Url(mac.Sum(nil))
	if signature != expectedSig {
		return nil
	}
	decodedBody, _ := base64.URLEncoding.WithPadding(base64.NoPadding).DecodeString(body)
	var payload map[string]interface{}
	json.Unmarshal(decodedBody, &payload)
	return payload
}

func jsonBytes(v interface{}) []byte {
	b, _ := json.Marshal(v)
	return b
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	http.HandleFunc("/auth/login", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method != "POST" {
			http.NotFound(w, r)
			return
		}
		var body struct {
			Username string `json:"username"`
			Password string `json:"password"`
		}
		json.NewDecoder(r.Body).Decode(&body)
		user, ok := users[body.Username]
		if !ok || user.Password != body.Password {
			w.WriteHeader(http.StatusUnauthorized)
			json.NewEncoder(w).Encode(map[string]string{"error": "Invalid credentials"})
			return
		}
		payload := map[string]interface{}{
			"sub":  body.Username,
			"role": user.Role,
			"iat":  time.Now().Unix(),
			"exp":  time.Now().Unix() + 3600,
		}
		token := createToken(payload)
		json.NewEncoder(w).Encode(map[string]interface{}{"token": token, "role": user.Role})
	})

	http.HandleFunc("/admin", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		authHeader := r.Header.Get("Authorization")
		if !strings.HasPrefix(authHeader, "Bearer ") {
			w.WriteHeader(http.StatusUnauthorized)
			json.NewEncoder(w).Encode(map[string]string{"error": "Unauthorized"})
			return
		}
		token := strings.TrimPrefix(authHeader, "Bearer ")
		payload := verifyToken(token)
		if payload == nil {
			w.WriteHeader(http.StatusUnauthorized)
			json.NewEncoder(w).Encode(map[string]string{"error": "Invalid token"})
			return
		}
		if payload["role"] != "admin" {
			w.WriteHeader(http.StatusForbidden)
			json.NewEncoder(w).Encode(map[string]string{"error": "Forbidden"})
			return
		}
		userKeys := make([]string, 0, len(users))
		for k := range users {
			userKeys = append(userKeys, k)
		}
		json.NewEncoder(w).Encode(map[string]interface{}{"message": "Admin panel", "users": userKeys})
	})

	http.ListenAndServe(":"+port, nil)
}

